import {readFileSync} from 'node:fs';
import {esc, arrow, button, pageIntro, relatedLinks} from './core-ui.mjs';

const [sample] = JSON.parse(readFileSync(new URL('../data/product-pages.json',import.meta.url),'utf8'));
const samplePhoto = sample.variants[0].images[0];
const samplePrice = new Intl.NumberFormat('en-GB',{style:'currency',currency:sample.currency}).format(sample.price);
const samplePath = `/products/${sample.slug}/`;
const sampleEmail = 'sample@example.invalid';
const sampleAddress = {firstName:'Sample',lastName:'Shopper',line1:'12 Example Lane',city:'Exampletown',postcode:'AB1 2CD'};

const preview = (text, label='A sample journey') => `<aside class="cm-preview" aria-label="Preview information"><strong>${esc(label)}</strong><p>${esc(text)}</p></aside>`;
const action = (label, attrs='', secondary=false) => `<button type="button" class="button${secondary?' cm-button-secondary':''}" ${attrs}>${esc(label)} ${arrow}</button>`;
const link = (label,href) => `<a class="text-link" href="${esc(href)}">${esc(label)} ${arrow}</a>`;
const status = (label, tone='') => `<span class="cm-status ${esc(tone)}">${esc(label)}</span>`;
const eyebrow = text => `<p class="eyebrow">${esc(text)}</p>`;
const picture = (src,alt,extra='') => `<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy" decoding="async" ${extra}>`;
const intro = (title,description,name,extra={}) => pageIntro({title,description,breadcrumbs:[{label:name}],className:'cm-intro',...extra});
const uiStatus = '<p class="cm-feedback" id="commerce-feedback" role="status" aria-live="polite"></p>';
const noScript = '<noscript><p class="cm-noscript">Turn on JavaScript to try the sample controls. The page content and collection links are still available.</p></noscript>';

function field({id,label,type='text',value='',placeholder='',readonly=false,required=false,full=false,autocomplete='off',max=100}) {
  return `<label class="field cm-field${full?' cm-field-wide':''}" for="${id}"><span>${esc(label)}</span><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="${autocomplete}" maxlength="${max}"${readonly?' readonly':''}${required?' required':''} aria-describedby="${id}-error"><small id="${id}-error" class="cm-field-error"></small></label>`;
}

function accountNav(current) {
  return `<nav class="cm-account-nav" aria-label="Account navigation">${[
    ['overview','Your overview','/account/'],['orders','Orders','/account/orders/'],['addresses','Addresses','/account/addresses/'],['preferences','Details & preferences','/account/preferences/'],['wishlist','Saved pieces','/wishlist/']
  ].map(([id,label,href])=>`<a href="${href}"${current===id?' aria-current="page"':''}><span>${esc(label)}</span>${arrow}</a>`).join('')}<div class="cm-account-nav-extra"><a href="/help/">A little help ${arrow}</a><a href="/account/login/">Leave sample account ${arrow}</a></div></nav>`;
}

function accountPage({title,description,name,current,content}) {
  return `${intro(title,description,name)}<section class="section-wrap cm-page-content">${preview('This is a sample account. No customer is signed in, and no real orders or personal details are shown.')}<div class="cm-account-layout">${accountNav(current)}<div class="cm-account-main">${content}</div></div></section>`;
}

function sampleLine({quantity=1,meta='Oat / M',compact=false}={}) {
  return `<div class="cm-sample-line${compact?' cm-sample-line-compact':''}"><a href="${samplePath}" tabindex="-1" aria-hidden="true">${picture(samplePhoto.src,samplePhoto.alt,'width="900" height="1600"')}</a><div>${eyebrow('Design sample')}<h3><a href="${samplePath}">${esc(sample.name)}</a></h3><p>${esc(meta)} <span aria-hidden="true">·</span> Quantity ${quantity}</p><strong>${samplePrice}</strong><small>Example unit price</small></div></div>`;
}

function orderSteps({current=3,returns=false}={}) {
  const names=returns?['Request prepared','Instructions supplied','Parcel received','Outcome updated']:['Order received','Getting ready','On its way','Delivered'];
  return `<ol class="cm-timeline" aria-label="${returns?'Sample return':'Sample delivery'} progress">${names.map((name,index)=>`<li class="${index<current?'is-complete':index===current?'is-current':''}"${index===current?' aria-current="step"':''}><span class="cm-timeline-mark" aria-hidden="true">${index<current?'✓':index+1}</span><div><strong>${esc(name)}</strong><small>${index===current?'Current sample stage':index<current?'Example completed stage':'Shown when available'}</small></div></li>`).join('')}</ol>`;
}

function receipt({checkout=false}={}) {
  return `<aside class="cm-receipt"><div class="cm-panel-heading"><h2>${checkout?'Your sample order':'A little overview'}</h2><span class="cm-caption">Preview</span></div><div data-cart-summary>${sampleLine({compact:true})}</div><dl class="cm-totals"><div><dt>Example items subtotal</dt><dd data-cart-subtotal>${samplePrice}</dd></div><div><dt>Delivery</dt><dd>Not calculated</dd></div><div><dt>Taxes & duties</dt><dd>Not calculated</dd></div><div class="cm-total-final"><dt>Payable total</dt><dd>Not available</dd></div></dl><p class="cm-small">The price is illustrative. No delivery, tax or payment amount is confirmed by this preview.</p>${checkout?'':`<a class="button cm-wide-button" href="/checkout/" data-checkout-link>Explore sample checkout ${arrow}</a>`}<a class="cm-subtle-link" href="/delivery/">About delivery</a></aside>`;
}

function basket() {
  return `${intro('Your shopping <em>bag.</em>','A good place to gather your next favourites.','Shopping basket')}<section class="section-wrap cm-page-content" data-commerce-page="basket">${preview('Try the bag with our sample cardigan. This product, its options and its price are illustrative; orders are not enabled.')}<div id="sample-bag-empty" class="cm-bag-empty"><div><h2>A little room<br><em>for something lovely.</em></h2><p>Your sample bag is empty. Explore the wardrobe, or add the design sample to try quantities, colours and checkout.</p><div class="cm-actions">${button('Explore the wardrobe','/shop/')}${action('Try a sample bag','data-add-sample',true)}</div></div><a href="${samplePath}" class="cm-bag-empty-photo">${picture(samplePhoto.src,'The sample Everyday Rib Cardigan in Oat','width="900" height="1600"')}<span>Meet the design sample ${arrow}</span></a></div><div id="sample-bag-filled" class="cm-checkout-layout" hidden><div class="cm-bag-items"><div class="cm-panel-heading"><h2>Your sample piece</h2><span data-bag-item-count>1 item</span></div><div id="bag-lines"><article class="cm-bag-item"><a href="${samplePath}" class="cm-bag-product-image">${picture(samplePhoto.src,samplePhoto.alt,'id="bag-product-photo" width="900" height="1600"')}</a><div class="cm-bag-product-copy">${eyebrow('Design sample')}<h3><a href="${samplePath}">${esc(sample.name)}</a></h3><p class="cm-example-price">${samplePrice}<small>Example unit price</small></p><div class="cm-bag-options"><label class="field" for="bag-colour"><span>Colour</span><select id="bag-colour">${sample.variants.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></label><label class="field" for="bag-size"><span>Size</span><select id="bag-size">${sample.sizes.map(s=>`<option${s==='M'?' selected':''}>${s}</option>`).join('')}</select></label></div><div class="cm-item-actions"><div class="cm-quantity" aria-label="Sample quantity"><button type="button" data-quantity-change="-1" aria-label="Decrease sample quantity">−</button><label class="sr-only" for="bag-quantity">Quantity</label><input id="bag-quantity" type="number" min="1" max="10" value="1" inputmode="numeric"><button type="button" data-quantity-change="1" aria-label="Increase sample quantity">+</button></div><button type="button" class="cm-inline-button" data-remove-sample>Remove</button></div></div></article></div><div class="cm-bag-note"><p>Found something in the collection?</p><p>Real product links take you to their current details and buying options. This bag is reserved for the design sample.</p>${link('Keep exploring','/shop/')}</div></div>${receipt()}</div>${uiStatus}${noScript}</section>`;
}

function checkout() {
  return `${intro('The finishing <em>touches.</em>','An unhurried checkout, with the details in one place.','Checkout')}<section class="section-wrap cm-page-content" data-commerce-page="checkout">${preview('Checkout design preview. Use the fictional details below. No address is saved, no order is submitted and no payment details are collected.')}<div id="checkout-empty" class="cm-inline-empty" hidden><div><h2>Your sample bag is empty.</h2><p>Add the sample cardigan to explore this checkout.</p></div>${action('Add the sample cardigan','data-add-sample')}</div><div class="cm-checkout-layout" id="checkout-layout"><div><ol class="cm-steps" aria-label="Checkout progress"><li data-checkout-step-label="0" aria-current="step"><span>1</span>Your details</li><li data-checkout-step-label="1"><span>2</span>Delivery</li><li data-checkout-step-label="2"><span>3</span>Review</li></ol><form id="preview-checkout-form" class="cm-form-panel" method="dialog" novalidate><section class="cm-checkout-step" data-checkout-step="0"><div class="cm-panel-heading"><h2>A place to call home.</h2></div><p class="cm-form-intro">These fictional details let you try the form. Any edits stay on this page only.</p><div class="cm-fields">${field({id:'checkout-email',label:'Email address',type:'email',value:sampleEmail,required:true,full:true})}${field({id:'checkout-first',label:'First name',value:sampleAddress.firstName,required:true})}${field({id:'checkout-last',label:'Last name',value:sampleAddress.lastName,required:true})}${field({id:'checkout-address',label:'Address',value:sampleAddress.line1,required:true,full:true})}${field({id:'checkout-city',label:'Town or city',value:sampleAddress.city,required:true})}${field({id:'checkout-postcode',label:'Postcode',value:sampleAddress.postcode,required:true,max:12})}<label class="field cm-field-wide" for="checkout-country"><span>Example destination</span><select id="checkout-country"><option value="GB">United Kingdom (sample)</option></select><small>This selection is for the layout, not a delivery-availability promise.</small></label></div><div class="cm-form-actions">${action('Continue to delivery','data-checkout-next="1"')}<button type="button" class="cm-inline-button" data-reset-checkout>Reset sample details</button></div></section><section class="cm-checkout-step" data-checkout-step="1" hidden><h2>A little closer to you.</h2><p class="cm-form-intro">Delivery options, prices and timing will be supplied by the connected checkout service.</p><label class="cm-choice-card"><input type="radio" name="preview-delivery" value="sample" checked><span><strong>Delivery option preview</strong><small>The delivery name, estimate and cost appear here when verified.</small></span><b>Not set</b></label><p class="cm-small">No delivery fee has been added. The payable total remains unavailable in this sample.</p><div class="cm-form-actions">${action('Review the sample order','data-checkout-next="2"')}<button type="button" class="cm-inline-button" data-checkout-back="0">Back to your details</button></div></section><section class="cm-checkout-step" data-checkout-step="2" hidden><h2>One last look.</h2><p class="cm-form-intro">Review the sample journey. This final step never charges a card or places an order.</p><div class="cm-review-address"><h3>Details entered in this preview</h3><p id="checkout-address-review"></p><button type="button" class="cm-inline-button" data-checkout-back="0">Edit details</button></div><div class="cm-payment-placeholder"><span class="cm-payment-mark" aria-hidden="true">□</span><div><h3>Secure payment will appear here.</h3><p>The payment provider is not connected. Card and bank details cannot be entered in this preview.</p></div></div><label class="cm-check"><input id="preview-checkout-understood" type="checkbox"><span>I understand this is a sample order and nothing will be purchased.</span></label><p class="cm-field-error" id="checkout-consent-error" role="alert"></p><div class="cm-form-actions">${action('Preview order confirmation','id="preview-place-order"')}<button type="button" class="cm-inline-button" data-checkout-back="1">Back to delivery</button></div><p class="cm-small">See the <a href="/terms-and-conditions/">terms preview</a> and <a href="/privacy-policy/">privacy information</a>.</p></section><p id="checkout-error" class="cm-feedback" role="alert"></p></form></div>${receipt({checkout:true})}</div>${uiStatus}${noScript}</section>`;
}

function confirmation() {
  return `<section class="section-wrap cm-page-content cm-confirmation" data-commerce-page="confirmation">${preview('This is an order-confirmation design preview. No order has been placed, no payment has been taken and no confirmation email has been sent.')}<div class="cm-confirmation-heading"><span class="cm-confirmation-mark" aria-hidden="true">✓</span><p class="eyebrow">Order confirmation preview</p><h1>That lovely<br><em>new-piece feeling.</em></h1><p>This is where a confirmed order and its next steps will appear.</p>${status('Sample reference: SAMPLE-001')}</div><div class="cm-confirmation-grid"><div class="cm-form-panel"><h2>Your sample pieces.</h2><div data-order-lines>${sampleLine()}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><div class="cm-order-facts"><div><span>Merchandise example</span><strong data-order-subtotal>${samplePrice}</strong></div><div><span>Payment outcome</span><strong>No payment attempted</strong></div></div></div><aside class="cm-next-steps"><h2>What comes next?</h2><ol><li><strong>A confirmation email</strong><p>The live service will send the verified order details after a successful purchase.</p></li><li><strong>Updates as it moves</strong><p>Shipment details will appear when the seller provides them.</p></li><li><strong>A helping hand</strong><p>Order support will always be within easy reach.</p></li></ol><div class="cm-actions">${button('View the sample order','/account/orders/sample-order/')}${link('Keep exploring','/shop/')}</div></aside></div></section>`;
}

function paymentRetry() {
  return `${intro('Let’s pick up<br><em>where you left off.</em>','A clear route back when a payment cannot be completed.','Payment retry')}<section class="section-wrap cm-page-content">${preview('This is the payment-retry screen preview. No payment was attempted and there is no failed transaction to resolve.')}<div class="cm-recovery-layout"><div class="cm-form-panel"><span class="cm-status cm-status-warm">Example: payment not completed</span><h2>Your sample bag is still here.</h2><p>A live checkout will show the payment outcome before offering another attempt. That helps avoid submitting the same order twice.</p><div class="cm-actions">${button('Return to sample checkout','/checkout/')}${link('Review the sample bag','/basket/')}</div></div><aside class="cm-recovery-aside"><h3>For a real payment question</h3><p>Check the status in the shop where you placed the order. If the outcome is unclear, contact that shop before trying again.</p>${link('Get help','/help/')}<a class="cm-subtle-link" href="https://wowfashion.com/">Visit the current WOW Fashion shop ↗</a></aside></div></section>`;
}

function authFrame({name,title,description,content}) {
  return `${intro(title,description,name)}<section class="section-wrap cm-page-content"><div class="cm-auth-layout"><div class="cm-auth-photo">${picture('/assets/homepage/layers-editorial.webp','A woman in an olive cardigan on a sunlit terrace','width="1024" height="1280"')}<div><h2>A little space<br><em>for your style.</em></h2><p>Saved pieces. Familiar favourites. One place to return to.</p></div></div><div class="cm-auth-form">${preview('Account services are not connected. The fields below show fictional details and cannot be used to sign in to a real account.','Account design preview')}${content}</div></div></section>`;
}

function login() {
  return authFrame({name:'Sign in',title:'Lovely to<br><em>see you again.</em>',description:'Your favourite pieces, all in one place.',content:`<h2>Welcome back.</h2><div class="cm-fields cm-fields-single">${field({id:'login-email',label:'Email address (sample)',type:'email',value:sampleEmail,readonly:true})}${field({id:'login-password',label:'Password field preview',type:'password',value:'sample-only',readonly:true})}</div><div class="cm-auth-meta"><span>Fictional details only</span><a href="/account/reset-password/">Forgotten password?</a></div>${button('Explore the sample account','/account/',{className:'cm-wide-button'})}<p class="cm-auth-switch">New here? <a href="/account/register/">See the account-creation page</a></p><div class="cm-auth-footer"><p>Shopping without an account?</p>${link('Explore the wardrobe','/shop/')}<a class="cm-subtle-link" href="https://wowfashion.com/">Visit the current shop for live account services ↗</a></div>`});
}

function register() {
  return authFrame({name:'Create an account',title:'A little more<br><em>your own.</em>',description:'A thoughtful home for your shopping details and saved pieces.',content:`<h2>Make room for your favourites.</h2><div class="cm-fields cm-fields-single">${field({id:'register-name',label:'Name (sample)',value:'Sample shopper',readonly:true})}${field({id:'register-email',label:'Email address (sample)',type:'email',value:sampleEmail,readonly:true})}${field({id:'register-password',label:'Password field preview',type:'password',value:'sample-only',readonly:true})}</div><label class="cm-check"><input type="checkbox" id="register-style-notes"><span>Style notes and collection news (sample preference).</span></label><p class="cm-small">This optional choice stays on this page. No marketing permission or customer account is created.</p>${button('Preview your account','/account/?preview=new',{className:'cm-wide-button'})}<p class="cm-auth-switch">Already have an account? <a href="/account/login/">View sign in</a></p><p class="cm-small">Real registration will use the approved <a href="/terms-and-conditions/">terms</a> and <a href="/privacy-policy/">privacy policy</a>. Guest shopping remains a separate journey.</p>`});
}

function resetPassword() {
  return `${intro('A fresh start.<br><em>Same lovely you.</em>','A simple account-recovery journey, with clear next steps.','Account recovery')}<section class="section-wrap cm-page-content cm-narrow" data-commerce-page="recovery">${preview('Recovery design preview. This page cannot send an email, change a password or access a real customer account.')}<div class="cm-form-panel"><h2>Recover your account.</h2><p class="cm-form-intro">A connected account service will use a private, time-limited link to help you regain access.</p>${field({id:'recovery-email',label:'Email address (sample)',type:'email',value:sampleEmail,readonly:true})}<div class="cm-form-actions">${action('Preview recovery instructions','data-recovery-preview')}<a class="cm-subtle-link" href="/account/login/">Back to sign in</a></div><section id="recovery-preview" class="cm-recovery-result" hidden tabindex="-1"><span class="cm-caption">Example email screen</span><h3>One little step back in.</h3><p>The recovery instructions would be sent to the account email if it is eligible. This wording avoids revealing whether an account exists.</p><p class="cm-small">No email has been sent from this preview.</p><button type="button" class="cm-inline-button" data-recovery-expired>View the expired-link example</button></section><section id="recovery-expired" class="cm-recovery-result" hidden tabindex="-1"><h3>This example link has expired.</h3><p>A live recovery flow will offer a new link without asking for an old password.</p><button type="button" class="cm-inline-button" data-recovery-preview>Return to the recovery example</button></section></div></section>`;
}

function accountOverview() {
  return accountPage({name:'Your account',current:'overview',title:'Your wardrobe,<br><em>at a glance.</em>',description:'The useful details, with a little room for inspiration.',content:`<div class="cm-account-welcome"><div><p class="eyebrow">Sample account</p><h2>Hello, sample shopper.</h2><p>Here’s where your orders, saved pieces and details come together.</p></div><span class="cm-account-monogram" aria-hidden="true">S</span></div><div class="cm-account-shortcuts"><a href="/account/orders/"><span>Orders</span><strong>1 <small>sample order</small></strong>${arrow}</a><a href="/wishlist/"><span>Saved pieces</span><strong>Your <em>shortlist</em></strong>${arrow}</a><a href="/account/addresses/"><span>Addresses</span><strong>2 <small>sample addresses</small></strong>${arrow}</a></div><div class="cm-panel-heading"><h2>A recent favourite.</h2>${link('All orders','/account/orders/')}</div><article class="cm-order-card"><div class="cm-order-card-top"><div><small>Sample order</small><h3>SAMPLE-001</h3></div>${status('Delivered · sample')}</div><div data-order-lines data-order-compact="true">${sampleLine({compact:true})}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><div class="cm-order-card-bottom"><span><span data-order-subtotal>${samplePrice}</span> example items subtotal</span>${link('View sample order','/account/orders/sample-order/')}</div></article><div class="cm-account-inspiration">${picture('/assets/homepage/details-still-life.webp','Oatmeal knitwear, ivory fabric and dusty-rose cloth','width="1536" height="1024"')}<div><h3>Something to<br><em>come back to.</em></h3><p>Save the pieces that catch your eye as you browse.</p>${link('Explore the wardrobe','/shop/')}</div></div>`});
}

function orders() {
  return accountPage({name:'Order history',current:'orders',title:'The pieces<br><em>you picked.</em>',description:'Your order history, with the next step always close by.',content:`<div data-commerce-page="orders"><div class="cm-panel-heading"><h2>Your orders</h2><label class="cm-select-label" for="order-status-filter"><span>Show</span><select id="order-status-filter"><option value="all">All sample orders</option><option value="progress">In progress</option><option value="delivered">Delivered</option></select></label></div><p class="cm-small" id="order-results-count" role="status">1 sample order</p><article class="cm-order-card" id="sample-order-card"><div class="cm-order-card-top"><div><small>Sample order reference</small><h3>SAMPLE-001</h3></div>${status('Delivered · sample')}</div><div data-order-lines>${sampleLine()}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><div class="cm-order-card-bottom"><span><span data-order-subtotal>${samplePrice}</span> example items subtotal</span><div>${link('Order details','/account/orders/sample-order/')}${link('Delivery example','/track-order/')}</div></div></article><div class="cm-empty-panel" id="orders-empty" hidden><h3>A little room for what’s next.</h3><p>There are no sample orders in this view. Try another filter or explore the collection.</p>${button('Explore the wardrobe','/shop/')}</div></div>`});
}

function orderDetail() {
  return accountPage({name:'Sample order details',current:'orders',title:'Every little<br><em>order detail.</em>',description:'A clear view of the piece, the delivery and the help available.',content:`<div class="cm-panel-heading"><div><p class="eyebrow">Sample order</p><h2>SAMPLE-001</h2></div>${status('Delivered · sample')}</div><div class="cm-order-detail-grid"><div><div class="cm-form-panel"><h3>What’s inside</h3><div data-order-lines>${sampleLine()}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><dl class="cm-totals"><div><dt>Example items subtotal</dt><dd data-order-subtotal>${samplePrice}</dd></div><div><dt>Delivery, tax and duties</dt><dd>Not calculated</dd></div><div><dt>Payment</dt><dd>Not attempted</dd></div></dl></div><div class="cm-order-support"><h3>Need a little help?</h3><p>Find the right next step, from caring for a piece to exploring the returns journey.</p><div class="cm-link-list">${link('Start a return preview','/returns/start/')}${link('Change or cancel an order','/cancel-order/')}${link('Product care guide','/care-guide/')}${link('Contact support','/contact/')}</div></div></div><aside><div class="cm-form-panel"><h3>Delivery example</h3>${orderSteps()}<p class="cm-small">All stages shown are illustrative. No real parcel is being tracked.</p></div><div class="cm-address-summary"><h3>Sample delivery address</h3><p>Sample Shopper<br>12 Example Lane<br>Exampletown<br>AB1 2CD</p><small>Fictional details used for layout only.</small></div><div class="cm-address-summary"><h3>Order documents</h3><p>An invoice or receipt will be available here when a real order service is connected.</p></div></aside></div>`});
}

function addresses() {
  return accountPage({name:'Address book',current:'addresses',title:'A place for<br><em>your favourites.</em>',description:'Keep the details that make delivery a little easier.',content:`<div data-commerce-page="addresses"><div class="cm-panel-heading"><h2>Your sample addresses</h2>${action('Add a sample address','data-add-address')}</div><p class="cm-small cm-space-after">You can edit these fictional examples. Changes stay on this page and reset when you leave.</p><div class="cm-address-grid" id="address-list"><article class="cm-address-card"><span class="cm-status">Default sample</span><h3>Home</h3><p>Sample Shopper<br>12 Example Lane<br>Exampletown<br>AB1 2CD</p></article><article class="cm-address-card"><h3>Another place</h3><p>Sample Shopper<br>24 Sample Street<br>Exampletown<br>AB1 3CD</p></article></div>${uiStatus}<div class="cm-undo-row" id="address-undo" hidden><span>Sample address removed.</span><button type="button" class="cm-inline-button" data-undo-address>Undo</button></div><dialog class="cm-dialog" id="address-dialog" aria-labelledby="address-dialog-title"><div class="cm-dialog-top"><h2 id="address-dialog-title">A new place.</h2><button type="button" class="cm-close" data-close-address aria-label="Close address editor">×</button></div><p class="cm-small">Use fictional details. This preview does not save personal information between pages.</p><form id="address-form" method="dialog" novalidate><div class="cm-fields">${field({id:'address-label',label:'Address name',value:'Another place',required:true,full:true,max:40})}${field({id:'address-first',label:'First name',value:sampleAddress.firstName,required:true})}${field({id:'address-last',label:'Last name',value:sampleAddress.lastName,required:true})}${field({id:'address-line',label:'Address',value:'36 Sample Road',required:true,full:true})}${field({id:'address-city',label:'Town or city',value:sampleAddress.city,required:true})}${field({id:'address-postcode',label:'Postcode',value:'AB1 4CD',required:true,max:12})}</div><label class="cm-check"><input type="checkbox" id="address-default"><span>Make this the default sample address</span></label><div class="cm-form-actions">${action('Save in this preview','data-save-address')}<button type="button" class="cm-inline-button" data-close-address>Cancel</button></div><p class="cm-feedback" id="address-error" role="alert"></p></form></dialog>${noScript}</div>`});
}

function preferences() {
  return accountPage({name:'Account preferences',current:'preferences',title:'The details<br><em>that make it yours.</em>',description:'Your profile and your choices, thoughtfully kept together.',content:`<div data-commerce-page="preferences"><div class="cm-form-panel"><h2>Your details</h2><p class="cm-form-intro">Try editing the sample name. This page is not connected to a customer profile.</p><form id="account-preferences-form" method="dialog" novalidate><div class="cm-fields">${field({id:'preference-first',label:'First name',value:'Sample',required:true})}${field({id:'preference-last',label:'Last name',value:'Shopper',required:true})}${field({id:'preference-email',label:'Email address (sample)',type:'email',value:sampleEmail,readonly:true,full:true})}</div><p class="cm-small">Live email and password changes require verification through the account service.</p><div class="cm-preference-section"><h3>A little inspiration</h3><p>Keep shopping messages separate from essential order updates.</p><label class="cm-check"><input id="preference-style" type="checkbox" checked><span>Style notes (sample preference)</span></label><label class="cm-check"><input id="preference-news" type="checkbox"><span>Collection news (sample preference)</span></label></div>${action('Preview saved preferences','data-save-preferences')}${uiStatus}</form></div><section class="cm-account-support"><h3>Your information, your choice.</h3><p>For a real account-access or deletion request, use the support route provided by the shop that holds your account.</p>${link('Contact & assistance','/contact/')}<a class="cm-subtle-link" href="/privacy-policy/">Read the privacy information</a></section></div>`});
}

function tracking() {
  return `${intro('A little closer<br><em>to your door.</em>','A simple place to check an order and find the right next step.','Track an order')}<section class="section-wrap cm-page-content" data-commerce-page="tracking">${preview('Tracking design preview. The sample reference below is fictional and does not look up a real customer or parcel.')}<div class="cm-tracking-layout"><div class="cm-form-panel"><h2>Find your order.</h2><p class="cm-form-intro">A live lookup will securely verify the order and the customer before showing delivery details.</p><div class="cm-fields cm-fields-single">${field({id:'tracking-reference',label:'Sample order reference',value:'SAMPLE-001',readonly:true})}${field({id:'tracking-email',label:'Sample customer email',type:'email',value:sampleEmail,readonly:true})}</div><div class="cm-form-actions">${action('Show sample tracking','data-show-tracking')}</div><p class="cm-small">For a real delivery update, follow the tracking link supplied by the shop in your order email.</p>${link('Get order help','/help/')}</div><div class="cm-tracking-result" id="tracking-result" hidden tabindex="-1"><div class="cm-panel-heading"><div><p class="eyebrow">Sample order</p><h2>SAMPLE-001</h2></div>${status('Delivered · example')}</div><div data-order-lines data-order-compact="true">${sampleLine({compact:true})}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><div id="tracking-ready">${orderSteps()}<div class="cm-tracking-note"><h3>One sample parcel.</h3><p>Live shipments will show the carrier and tracking link when available. Split deliveries will appear as separate parcels.</p></div></div><div class="cm-empty-panel" id="tracking-unavailable" hidden><h3>A little update is on its way.</h3><p>In this example, tracking has not been supplied yet. An order can be confirmed before its tracking details are available.</p>${link('Contact & assistance','/contact/')}</div><button type="button" class="cm-inline-button" data-toggle-tracking>View tracking-not-ready example</button></div><div class="cm-tracking-intro" id="tracking-intro">${picture('/assets/homepage/details-still-life.webp','A closer look at soft knitwear and folded fabric','width="1536" height="1024"')}<h3>The details, without the guesswork.</h3><p>Order identity, parcel updates and support belong in one clear view.</p></div></div>${uiStatus}</section>`;
}

function startReturn() {
  return `${intro('Let’s find<br><em>the right next step.</em>','A considered return or exchange starts with a few clear details.','Start a return')}<section class="section-wrap cm-page-content" data-commerce-page="return-start">${preview('Returns design preview. This form uses a sample order and does not submit a return, check eligibility or create a postage label.')}<div class="cm-return-layout"><form id="return-preview-form" class="cm-form-panel" method="dialog" novalidate><div class="cm-panel-heading"><div><p class="eyebrow">Sample order</p><h2>SAMPLE-001</h2></div>${status('Delivered · sample')}</div><p class="cm-small" data-order-source>A standalone sample order. Complete the sample checkout to view your selected pieces here.</p><div id="return-item-options"><label class="cm-return-product"><input type="checkbox" id="return-item" checked><span>${picture(samplePhoto.src,samplePhoto.alt,'width="900" height="1600"')}<span><strong>${esc(sample.name)}</strong><small>Oat / M · ${samplePrice} example price</small></span></span></label></div><p class="cm-field-error" id="return-item-error" role="alert"></p><div class="cm-fields"><label class="field cm-field-wide" for="return-reason"><span>Reason for the selected sample pieces</span><select id="return-reason" required aria-describedby="return-reason-error"><option value="">Choose a reason</option><option value="fit">The fit isn’t quite right</option><option value="colour">The colour isn’t what I expected</option><option value="fault">There is a fault or damage</option><option value="other">Something else</option></select><small id="return-reason-error" class="cm-field-error"></small></label></div><fieldset class="cm-resolution"><legend>Your preferred outcome</legend><label class="cm-choice-card"><input type="radio" name="return-resolution" value="refund" checked><span><strong>Refund request preview</strong><small>Eligibility and refund details need confirmation by the seller.</small></span></label><label class="cm-choice-card"><input type="radio" name="return-resolution" value="exchange"><span><strong>Exchange request preview</strong><small>Alternative options depend on availability and the actual policy.</small></span></label></fieldset><div id="return-exchange-options" hidden><label class="field" for="return-exchange-size"><span>Preferred sample size</span><select id="return-exchange-size">${sample.sizes.map(size=>`<option${size==='L'?' selected':''}>${size}</option>`).join('')}</select></label></div><label class="cm-check"><input type="checkbox" id="return-understood"><span>I understand this is a preview and no return request will be sent.</span></label><p class="cm-field-error" id="return-understood-error" role="alert"></p><div class="cm-form-actions">${action('Preview return request','data-submit-return')}</div></form><aside class="cm-return-guidance"><h2>A little guidance.</h2><p>Before sending any item back, check the seller’s current return instructions and eligibility requirements.</p><div class="cm-guidance-item"><h3>Something faulty?</h3><p>Keep the relevant order details and a clear description of the issue ready for support.</p>${link('Faulty-item help','/warranty/')}</div><div class="cm-guidance-item"><h3>Not quite your fit?</h3><p>Compare the individual piece’s measurements before choosing an alternative.</p>${link('Find your fit','/size-guide/')}</div>${link('Read the returns page','/returns/')}</aside></div>${noScript}</section>`;
}

function returnStatus() {
  return `${intro('Every step,<br><em>a little clearer.</em>','A calm place to follow a return or exchange.','Return status')}<section class="section-wrap cm-page-content" data-commerce-page="return-status">${preview('This is a return-status design preview. No request has been sent, no item has been received and no refund is being processed.')}<div class="cm-return-status-layout"><div class="cm-form-panel"><div class="cm-panel-heading"><div><p class="eyebrow">Sample return</p><h2>SAMPLE-RETURN</h2></div>${status('Preview prepared')}</div><div data-return-lines>${sampleLine({compact:true})}</div><dl class="cm-totals"><div><dt>Example items subtotal</dt><dd data-return-subtotal>${samplePrice}</dd></div><div><dt>Preferred outcome</dt><dd id="return-summary-resolution">Refund request preview</dd></div><div><dt>Reason</dt><dd id="return-summary-reason">No preview reason selected yet</dd></div><div><dt>Real request status</dt><dd>Not submitted</dd></div></dl>${link('Change the sample request','/returns/start/')}</div><div class="cm-form-panel"><h2>What the journey looks like.</h2>${orderSteps({current:0,returns:true})}<p class="cm-small">In a live journey, wait for the seller’s instructions before posting an item. Timing and the final outcome depend on the actual policy and order.</p>${link('Returns & assistance','/returns/')}</div></div></section>`;
}

