function loyalty() {
  return `${intro('A little more<br><em>WOW.</em>','A thoughtful place for a future rewards community.','Rewards')}<section class="section-wrap cm-page-content" data-commerce-page="rewards">${preview('Rewards programme concept. Membership, points and benefits are not active, and no rewards are earned by browsing this preview.','Programme preview')}<div class="cm-rewards-hero"><div><h2>Good style.<br><em>Lovely possibilities.</em></h2><p>A future rewards space could bring your favourite pieces, account details and member news together. Its benefits and terms will be confirmed before joining becomes available.</p><div class="cm-actions">${button('Explore the sample account','/account/')}${link('Visit your wishlist','/wishlist/')}</div></div><div class="cm-member-card"><span class="cm-member-brand">WOW</span><span>Your little<br><em>style circle.</em></span><small>Membership design preview</small></div></div><div class="cm-reward-tabs" role="group" aria-label="Explore the rewards concept"><button type="button" data-reward-tab="overview" aria-pressed="true">A place for you</button><button type="button" data-reward-tab="rewards" aria-pressed="false">Your rewards</button><button type="button" data-reward-tab="questions" aria-pressed="false">A few details</button></div><section data-reward-panel="overview" class="cm-reward-panel"><div class="cm-reward-copy"><h3>Keep what you love close.</h3><p>Your wishlist already gives you a place to save the pieces that catch your eye. The account designs show how a future member space can sit alongside it.</p>${link('Save your next favourite','/shop/')}</div>${picture('/assets/homepage/details-still-life.webp','A tactile study of knitwear and ivory fabric','width="1536" height="1024"')}</section><section data-reward-panel="rewards" class="cm-reward-panel" hidden><div class="cm-empty-panel"><h3>A little room for future rewards.</h3><p>No points, vouchers or benefits have been issued. This space will show confirmed rewards if a programme is introduced.</p>${link('Explore the wardrobe','/shop/')}</div></section><section data-reward-panel="questions" class="cm-reward-panel" hidden><div class="cm-reward-faq"><details><summary>Can I join a rewards programme now?<span aria-hidden="true">+</span></summary><p>No. This page is a design concept. Joining becomes available only after the programme and its terms are approved.</p></details><details><summary>Am I earning points while I browse?<span aria-hidden="true">+</span></summary><p>No. The preview does not award points or track purchases for rewards.</p></details><details><summary>Can I save pieces without joining?<span aria-hidden="true">+</span></summary><p>Yes. Use the hearts on product cards to keep a wishlist on this device. You can remove saved pieces whenever you like.</p></details></div></section></section>`;
}

export function renderCommercePages({catalog,corePages}={}) {
  const definitions = [
    ['basket','Your shopping bag',basket,['Commerce platform','Verified live prices, stock and delivery costs']],
    ['checkout','Checkout',checkout,['Secure checkout and payment provider','Delivery, taxes and approved purchase terms']],
    ['confirmation','Order confirmation',confirmation,['Verified payment outcome','Private order data and confirmation email service']],
    ['payment-retry','Payment retry',paymentRetry,['Payment provider status','Idempotent order and payment retry handling']],
    ['login','Sign in',login,['Customer authentication provider']],
    ['register','Create an account',register,['Customer registration provider','Approved consent and account terms']],
    ['reset','Account recovery',resetPassword,['Secure recovery links and transactional email service']],
    ['account','Your account',accountOverview,['Authenticated customer session and profile data']],
    ['orders','Order history',orders,['Authenticated, customer-scoped order service']],
    ['order','Order details',orderDetail,['Authenticated per-order access','Verified shipments and invoices']],
    ['addresses','Address book',addresses,['Authenticated address service','Address validation and verified changes']],
    ['preferences','Account details and preferences',preferences,['Authenticated profile service','Email preference service and sensitive-change verification']],
    ['tracking','Track an order',tracking,['Private order identity verification','Carrier and supplier tracking data']],
    ['return-start','Start a return or exchange',startReturn,['Approved return process and eligibility','Private returns service']],
    ['return-status','Return status',returnStatus,['Private returns service and refund updates']],
    ['404','Page not found',notFound,[]],
    ['error','Service unavailable',serviceError,[]],
    ['newsletter','Style notes',newsletter,['Email marketing provider','Approved consent and confirmation flow']],
    ['unsubscribe','Email preferences',emailPreferences,['Secure email-provider preference link and suppression service']],
    ['gift','Gift cards',giftCards,['Gift-card issuing and redemption service','Approved gift-card values and terms']],
    ['loyalty','Rewards',loyalty,['Approved rewards programme','Membership and rewards service']]
  ];
  const fallbackPaths={basket:'/basket/',checkout:'/checkout/',confirmation:'/order-confirmation/','payment-retry':'/checkout/payment-failed/',login:'/account/login/',register:'/account/register/',reset:'/account/reset-password/',account:'/account/',orders:'/account/orders/',order:'/account/orders/sample-order/',addresses:'/account/addresses/',preferences:'/account/preferences/',tracking:'/track-order/','return-start':'/returns/start/','return-status':'/returns/status/','404':'/404/',error:'/service-unavailable/',newsletter:'/newsletter/',unsubscribe:'/email-preferences/',gift:'/gift-cards/',loyalty:'/rewards/'};
  return definitions.map(([shortId,title,render,dependencies])=>{
    const id='core-'+shortId;
    const inventory=corePages?.find(page=>page.id===id);
    const path=shortId==='order'?fallbackPaths.order:inventory?.path||fallbackPaths[shortId];
    const config={sample:{id:sample.id,name:sample.name,price:sample.price,currency:sample.currency,sizes:sample.sizes,variants:sample.variants.map(v=>({id:v.id,name:v.name,image:v.images[0].src,alt:v.images[0].alt}))}};
    return {id,path,title,description:inventory?.purpose||`${title} at WOW Fashion.`,kind:['404','error'].includes(shortId)?'system':'commerce',body:`<div class="cm-page">${render()}</div><script type="application/json" id="commerce-page-data">${JSON.stringify(config).replaceAll('<','\\u003c')}</script>`,styles:['/core-commerce.css'],scripts:['/core-commerce.js'],status:dependencies.length?'Integration required':'Built',dependencies};
  });
}
